DROP TABLE IF EXISTS `ai_memories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_memories` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '记忆ID',
  `user_id` int NOT NULL COMMENT '用户ID(绑定 users.id)',
  `question` text NOT NULL COMMENT '用户提问/识别出的题目',
  `answer` text COMMENT 'AI回答',
  `image_url` varchar(255) DEFAULT NULL COMMENT '题目图片地址(可选)',
  `major` varchar(50) DEFAULT NULL COMMENT '大类(语文/高数/大物/离散/英语/py/历史/地理/政治)',
  `sub` varchar(100) DEFAULT NULL COMMENT '小类(仅高数目前有)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_user_time` (`user_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI对话记忆(每用户最近5条)';
