DROP TABLE IF EXISTS `wrong_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wrong_questions` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '错题ID',
  `user_id` int NOT NULL COMMENT '用户ID(绑定 users.id)',
  `major` varchar(50) NOT NULL COMMENT '大类',
  `sub` varchar(100) NOT NULL DEFAULT '' COMMENT '小类(高数才有，其他为空)',
  `question` text NOT NULL COMMENT '题目内容',
  `answer` text COMMENT 'AI解答/解析',
  `image_url` varchar(255) DEFAULT NULL COMMENT '题目图片地址(可选)',
  `source` varchar(20) NOT NULL DEFAULT 'AI' COMMENT '错题来源(老师/AI)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '加入时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_major` (`user_id`,`major`),
  KEY `idx_user_sub` (`user_id`,`sub`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户错题集';
